406			throw new AxiError(
407				"ado.area must not use backslash escapes",
408				"VALIDATION_ERROR",
409				["Use a TOML literal string instead: ado.area = 'Internal\\Firstmate'"],
410			);
411		}
412		const states: AdoConfig["states"] = {
413			queued: stateNames(values.state_queued, ADO_DEFAULTS.states.queued),
414			in_flight: stateNames(
415				values.state_in_flight,
416				ADO_DEFAULTS.states.in_flight,
417			),
418			done: stateNames(values.state_done, ADO_DEFAULTS.states.done),
419		};
420		const queuedStates = new Set(states.queued.map((name) => name.toLowerCase()));
