338	function resolveAdo(
339		table: Record<string, string>,
340		env: NodeJS.ProcessEnv,
341	): AdoConfig | undefined {
342		const values: Record<string, string> = {};
343		for (const [key, raw] of Object.entries(table)) {
344			if (
345				(key === "org" && env.TASKS_AXI_ADO_ORG !== undefined) ||
346				(key === "project" && env.TASKS_AXI_ADO_PROJECT !== undefined) ||
347				(key === "area" && env.TASKS_AXI_ADO_AREA !== undefined)
348			) {
349				continue;
350			}
351			const source = `ado.${key}`;
352			values[key] = requireTomlString(parseTomlValue(raw, source), source);
353		}
354		const org = env.TASKS_AXI_ADO_ORG ?? values.org;
355		const project = env.TASKS_AXI_ADO_PROJECT ?? values.project;
356		const area = env.TASKS_AXI_ADO_AREA ?? values.area;
357		const workItemType = values.work_item_type ?? ADO_DEFAULTS.workItemType;
358		for (const [name, value] of [
359			["org", org],
360			["project", project],
361			["work_item_type", workItemType],
362		] as const) {
363			if (
364				value !== undefined &&
365				(value.trim() === "" || value !== value.trim() || /[\r\n]/.test(value))
366			) {
367				throw new AxiError(
368					`ado.${name} must be a non-empty single line without surrounding whitespace`,
369					"VALIDATION_ERROR",
370				);
371			}
372		}
373		if (area !== undefined) {
374			if (area.trim() === "") {
375				throw new AxiError("ado.area must not be empty", "VALIDATION_ERROR", [
376					"Remove ado.area or unset TASKS_AXI_ADO_AREA to use the whole project",
377				]);
378			}
379			if (area !== area.trim() || /[\r\n]/.test(area)) {
380				throw new AxiError(
381					"ado.area must be a single line without surrounding whitespace",
382					"VALIDATION_ERROR",
383				);
384			}
385			if (area.includes("\\\\")) {
386				throw new AxiError(
387					"ado.area must use single backslash separators",
388					"VALIDATION_ERROR",
389					["Use an area path like 'Internal\\Firstmate'"],
390				);
391			}
392		}
393		if (!org && !project && Object.keys(values).length === 0) return undefined;
394		if (!org || !project) {
