396				"The ado backend needs both `[ado] org` and `[ado] project`",
397				"VALIDATION_ERROR",
398				['Set `[ado] org = "contoso"` and `project = "Internal"` in .tasks.toml'],
399			);
400		}
401		if (
402			env.TASKS_AXI_ADO_AREA === undefined &&
