 71	  Archive-body, prune, render, and CLI move are Markdown-only and unavailable with ADO.
 72	examples:
 73	  tasks-axi
 74	  tasks-axi add homemux-h7 "owns HomeMux end to end" --kind secondmate --start
 75	  tasks-axi list --state queued
 76	  tasks-axi show homemux-h7 --full
 77	  tasks-axi done sm-idle-handoff-q8 --pr https://github.com/o/r/pull/42
 78	  tasks-axi block fm-x --by treehouse-lease-t4
 79	  tasks-axi hold fm-x --reason "captain decision pending" --kind captain
 80	  tasks-axi ready
 81	  tasks-axi public-followup ready --json
 82	  tasks-axi setup hooks
 83	`;
 84	
 85	type CommandFn = (args: string[], ctx?: TasksContext) => Promise<string>;
 86	
 87	// Canonical verbs plus the AXI/firstmate aliases (create/view/edit/delete/close).
 88	const COMMANDS: Record<string, CommandFn> = {
 89		add: withContext(addCommand),
 90		create: withContext(addCommand),
 91		list: withContext(listCommand),
 92		show: withContext(showCommand),
 93		view: withContext(showCommand),
 94		start: withContext(startCommand),
 95		done: withContext(doneCommand),
 96		close: withContext(doneCommand),
 97		reopen: withContext(reopenCommand),
 98		update: withContext(updateCommand),
 99		edit: withContext(updateCommand),
100		rm: withContext(rmCommand),
101		delete: withContext(rmCommand),
102		block: withContext(blockCommand),
103		unblock: withContext(unblockCommand),
104		hold: withContext(holdCommand),
105		unhold: withContext(unholdCommand),
106		ready: withContext(readyCommand),
107		"public-followup": withContext(publicFollowupCommand),
108		mv: withContext(mvCommand),
109		prune: withContext(pruneCommand),
110		render: withContext(renderCommand),
111		setup: (args) => setupCommand(args),
112	};
113	
114	const COMMAND_HELP: Record<string, string> = {
115		add: ADD_HELP,
116		create: ADD_HELP,
117		list: LIST_HELP,
118		show: SHOW_HELP,
119		view: SHOW_HELP,
120		start: START_HELP,
121		done: DONE_HELP,
122		close: DONE_HELP,
123		reopen: REOPEN_HELP,
124		update: UPDATE_HELP,
125		edit: UPDATE_HELP,
126		rm: RM_HELP,
127		delete: RM_HELP,
128		block: BLOCK_HELP,
129		unblock: UNBLOCK_HELP,
130		hold: HOLD_HELP,
131		unhold: UNHOLD_HELP,
132		ready: READY_HELP,
133		"public-followup": PUBLIC_FOLLOWUP_HELP,
134		mv: MV_HELP,
135		prune: PRUNE_HELP,
136		render: RENDER_HELP,
137		setup: SETUP_HELP,
138	};
139	
140	export async function main(options: MainOptions = {}): Promise<void> {
141		const argv = options.argv ?? process.argv.slice(2);
142		// The noun `task` is optional: `tasks-axi task add ...` === `tasks-axi add ...`.
143		const normalized = argv[0] === "task" ? argv.slice(1) : argv;
144		if (normalized[0] === "public-followup" && normalized[2] === "--help") {
145			const help = publicFollowupSubcommandHelp(normalized[1]);
146			if (help !== undefined) {
147				(options.stdout ?? process.stdout).write(help);
148				return;
149			}
150		}
151	
152		await runAxiCli<TasksContext | undefined>({
153			argv: normalized,
154			description: DESCRIPTION,
155			version: VERSION,
156			topLevelHelp: TOP_HELP,
157			...(options.stdout ? { stdout: options.stdout } : {}),
158			home: withContext(homeCommand),
159			commands: COMMANDS,
160			getCommandHelp: (command) => COMMAND_HELP[command],
161		});
162	}
163	
164	/** Strip the global --backend/--file flags and run the handler on the rest. */
165	function withContext(handler: CommandFn): CommandFn {
166		return (args) => {
167			const { backend, file, stripped, suggestionGlobals } =
168				parseGlobalFlags(args);
169			const ctx = resolveTasksContext(
170				{
171					...(backend !== undefined ? { backend } : {}),
172					...(file !== undefined ? { file } : {}),
173				},
174				suggestionGlobals,
175			);
176			return handler(stripped, ctx);
177		};
178	}
179	
180	function parseGlobalFlags(args: string[]): {
181		backend?: string;
182		file?: string;
183		stripped: string[];
184		suggestionGlobals?: SuggestionGlobals;
185	} {
186		const stripped: string[] = [];
187		let backend: string | undefined;
188		let file: string | undefined;
189	
190		for (let i = 0; i < args.length; i++) {
191			const arg = args[i];
192			if (arg === "--backend") {
193				const value = requireFlagValue(args, i, "--backend");
194				backend = requireNonEmptyGlobalFlagValue("--backend", value);
195				i++;
196				continue;
197			}
198			if (arg.startsWith("--backend=")) {
199				backend = requireNonEmptyGlobalFlagValue(
200					"--backend",
201					arg.slice("--backend=".length),
202				);
203				continue;
204			}
205			if (arg === "--file") {
206				const value = requireFlagValue(args, i, "--file");
207				file = requireNonEmptyGlobalFlagValue("--file", value);
208				i++;
209				continue;
210			}
211			if (arg.startsWith("--file=")) {
212				file = requireNonEmptyGlobalFlagValue(
213					"--file",
214					arg.slice("--file=".length),
215				);
216				continue;
217			}
218			stripped.push(arg);
219		}
220	
221		return {
222			...(backend ? { backend } : {}),
223			...(file ? { file } : {}),
224			stripped,
225			...(backend !== undefined || file !== undefined
226				? {
227						suggestionGlobals: {
228							...(backend !== undefined ? { backend } : {}),
229							...(file !== undefined ? { file } : {}),
230						},
231					}
232				: {}),
233		};
234	}
235	
236	function requireNonEmptyGlobalFlagValue(flag: string, value: string): string {
237		return requireNonEmptySingleLineFlagValue(flag, value) ?? value;
238	}

