116	export async function startCommand(
117	  rawArgs: string[],
118	  context?: TasksContext,
119	): Promise<string> {
120	  const { store } = requireCtx(context);
121	  const args = [...rawArgs];
122	  const json = takeBoolFlag(args, "--json");
123	  const positionals = requirePositionals(args, 1, 1, START_HELP.split("\n")[0]);
124	  const id = requireId(positionals[0], "id");
125	
126	  const current = await store.get(id);
127	  if (!current) throw notFound(id, { globals: context?.suggestionGlobals });
128	
129	  const already = current.state === "in_flight";
130	  const task = already ? current : await store.transition(id, "in_flight");
131	  const all = (await store.list({})).items;
132	  return renderMutation({
133	    json,
134	    confirm: already
135	      ? `start ${id} already in flight`
136	      : `start ${id} -> ${stateLabel(task.state)}`,
137	    already,
138	    jsonPayload: {
139	      ok: true,
140	      action: "start",
141	      ...(already ? { already: true } : {}),
142	      task: taskToJson(task, all),
143	    },
144	    suggestions: getSuggestions({
145	      action: "start",
146	      id,
147	      state: task.state,
148	      globals: context?.suggestionGlobals,
149	    }),
150	  });
151	}
