334	function requireHoldReason(value: string | undefined): string {
335	  const checked = requireNonEmptySingleLineFlagValue("--reason", value);
336	  if (checked === undefined) {
337	    throw new AxiError("--reason <text> is required", "VALIDATION_ERROR", [
338	      'Pass a reason, e.g. --reason "captain decision pending"',
339	    ]);
340	  }
341	  if (/[()]/.test(checked)) {
342	    throw new AxiError(
343	      "--reason must not contain parentheses",
