351	function parseHoldKind(value: string | undefined): HoldKind | undefined {
352	  const checked = requireNonEmptySingleLineFlagValue("--kind", value);
353	  if (checked === undefined) return undefined;
354	  if (!(HOLD_KINDS as readonly string[]).includes(checked)) {
355	    throw new AxiError(
356	      `--kind must be one of ${HOLD_KINDS.join(", ")}`,
357	      "VALIDATION_ERROR",
358	    );
359	  }
360	  return checked as HoldKind;
