363	function parseDateFlag(
364	  flag: string,
365	  value: string | undefined,
366	): string | undefined {
367	  const checked = requireNonEmptySingleLineFlagValue(flag, value);
368	  if (checked === undefined) return undefined;
369	  if (!/^\d{4}-\d{2}-\d{2}$/.test(checked)) {
370	    throw new AxiError(`${flag} must be YYYY-MM-DD`, "VALIDATION_ERROR");
371	  }
372	  return checked;
373	}
