238	/** The `(pr X, report Y)` parenthetical for a done confirmation, omitted when bare. */
239	function doneExtras(
240	  pr: string | undefined,
241	  report: string | undefined,
242	): string {
243	  const parts: string[] = [];
244	  if (pr !== undefined) parts.push(`pr ${pr}`);
245	  if (report !== undefined) parts.push(`report ${report}`);
246	  return parts.length > 0 ? ` (${parts.join(", ")})` : "";
247	}
248	
249	/** A trailing `; pruned N` note, shown only when something was archived. */
250	function prunedNote(pruned: number): string {
251	  return pruned > 0 ? `; pruned ${pruned}` : "";
252	}
253	
254	async function pruneDone(
255	  store: Store,
256	  keep: number,
257	  noPrune: boolean,
258	): Promise<number> {
259	  if (noPrune || !store.prune) return 0;
260	  const result = await store.prune({
261	    state: "done",
262	    keep,
263	    archive: true,
264	  });
265	  return result.archived;
266	}
267	
268	function doneMetadataPatch(
269	  pr: string | undefined,
270	  report: string | undefined,
271	  note: string | undefined,
272	): TaskPatch {
273	  const patch: TaskPatch = {};
274	  const addLinks: TaskLink[] = [];
275	  if (pr !== undefined) addLinks.push({ kind: "pr", url: pr });
276	  if (report !== undefined) addLinks.push({ kind: "report", url: report });
277	  if (addLinks.length > 0) patch.addLinks = addLinks;
278	  if (note !== undefined) patch.addBodyLines = [note];
279	  return patch;
280	}
