334	function requireHoldReason(value: string | undefined): string {
335	  const checked = requireNonEmptySingleLineFlagValue("--reason", value);
336	  if (checked === undefined) {
337	    throw new AxiError("--reason <text> is required", "VALIDATION_ERROR", [
338	      'Pass a reason, e.g. --reason "captain decision pending"',
339	    ]);
340	  }
341	  if (/[()]/.test(checked)) {
342	    throw new AxiError(
343	      "--reason must not contain parentheses",
344	      "VALIDATION_ERROR",
345	      ["Parentheses are reserved for markdown hold tags"],
346	    );
347	  }
348	  return checked.trim();
349	}
350	
351	function parseHoldKind(value: string | undefined): HoldKind | undefined {
352	  const checked = requireNonEmptySingleLineFlagValue("--kind", value);
353	  if (checked === undefined) return undefined;
354	  if (!(HOLD_KINDS as readonly string[]).includes(checked)) {
355	    throw new AxiError(
356	      `--kind must be one of ${HOLD_KINDS.join(", ")}`,
357	      "VALIDATION_ERROR",
358	    );
359	  }
360	  return checked as HoldKind;
361	}
362	
363	function parseDateFlag(
364	  flag: string,
365	  value: string | undefined,
366	): string | undefined {
367	  const checked = requireNonEmptySingleLineFlagValue(flag, value);
368	  if (checked === undefined) return undefined;
369	  if (!/^\d{4}-\d{2}-\d{2}$/.test(checked)) {
370	    throw new AxiError(`${flag} must be YYYY-MM-DD`, "VALIDATION_ERROR");
371	  }
372	  return checked;
373	}
374	
375	function sameHold(left: Hold | undefined, right: Hold | undefined): boolean {
376	  return (
377	    left?.reason === right?.reason &&
378	    left?.kind === right?.kind &&
379	    left?.until === right?.until
380	  );
381	}
