494	    ...(kind !== undefined ? { kind } : {}),
495	    ...(until !== undefined ? { until } : {}),
496	  };
497	  const already = sameHold(current.hold, hold);
498	  const task = already ? current : (await store.update(id, { hold })).task;
499	  const all = (await store.list({})).items;
500	  return renderMutation({
501	    json,
502	    confirm: already
503	      ? `hold ${id} already held`
504	      : `hold ${id} -> held${holdAttrs(hold)}`,
505	    already,
506	    jsonPayload: {
507	      ok: true,
508	      action: "hold",
509	      ...(already ? { already: true } : {}),
510	      task: taskToJson(task, all),
511	    },
512	    detail: renderTaskDetail(task, all, false, showFullTextHint(task)),
513	    suggestions:
514	      task.kind === PUBLIC_FOLLOWUP_KIND
