588	  const includeHeld = takeBoolFlag(args, "--include-held");
589	  requirePositionals(args, 0, 0, READY_HELP.split("\n")[0]);
590	
591	  const all = (await store.list({})).items;
592	  let items = readyTasks(all);
593	  const blocked = blockedIds(all);
594	  let held = heldTasks(all).filter(
595	    (t) =>
596	      t.state === "queued" &&
597	      t.kind !== PUBLIC_FOLLOWUP_KIND &&
598	      !blocked.has(t.id),
599	  );
600	  let publicFollowups = readyPublicFollowups(all);
601	  if (repo) items = items.filter((t) => t.repo === repo);
602	  if (repo) held = held.filter((t) => t.repo === repo);
603	  if (repo) publicFollowups = publicFollowups.filter((t) => t.repo === repo);
604	  const isEmpty = items.length === 0;
605	
606	  const blocks: string[] = [formatCountLine({ count: items.length })];
607	  if (isEmpty) {
608	    blocks.push("ready: 0 unblocked queued tasks");
609	  } else {
610	    blocks.push(renderTaskList("ready", items, all));
611	  }
612	  if (publicFollowups.length > 0) {
613	    blocks.push(
614	      renderTaskList("ready_public_followups", publicFollowups, all, [
615	        { type: "field", key: "delivery_state" },
616	      ]),
617	    );
618	  } else {
619	    blocks.push("ready_public_followups: 0 delivery-ready obligations");
620	  }
621	  if (includeHeld && held.length > 0) {
622	    blocks.push(
623	      renderTaskList("held", held, all, [
624	        { type: "field", key: "hold_reason" },
625	        { type: "field", key: "hold_kind" },
626	        { type: "field", key: "hold_until" },
627	      ]),
628	    );
629	  }
630	  blocks.push(
631	    renderHelp(
632	      getSuggestions({
633	        action: "ready",
634	        isEmpty,
635	        globals: context?.suggestionGlobals,
636	        filters: {
637	          ...(repo !== undefined ? { repo } : {}),
638	        },
639	      }),
640	    ),
641	  );
642	  return renderOutput(blocks);
643	}
