645	function resolveBacklogTarget(to: string): string {
646	  const base = isAbsolute(to) ? to : resolve(process.cwd(), to);
647	  if (existsSync(base) && statSync(base).isDirectory()) {
648	    for (const candidate of ["data/backlog.md", "backlog.md"]) {
649	      const full = resolve(base, candidate);
650	      if (existsSync(full)) return full;
651	    }
652	    return resolve(base, "data/backlog.md");
653	  }
654	  return base;
