1062		private relationValue(
1063			ownerId: string,
1064			dep: Dep,
1065			workItemId: number,
1066		): { rel: string; url: string; attributes?: Record<string, unknown> } {
1067			const rel =
1068				dep.type === "blocked-by"
1069					? REL_BLOCKED_BY
1070					: dep.type === "parent"
1071						? REL_PARENT
1072						: REL_RELATED;
1073			const marker = dep.type === "parent" ? PARENT_MARKER : DISCOVERED_MARKER;
1074			const text =
