1303				);
1304			}
1305	
1306			const changed: TaskUpdateChange[] = [];
1307			const mark = (field: TaskUpdateChange) => {
1308				if (!changed.includes(field)) changed.push(field);
1309			};
1310			const ops: JsonPatchOp[] = [];
1311	
1312			if (patch.title !== undefined) {
1313				const title = normalizeTitle(patch.title);
1314				if (task.title !== title) {
1315					task.title = title;
1316					mark("title");
1317				}
1318			}
1319			if (patch.body !== undefined) {
1320				const body = patch.body || undefined;
1321				if (task.body !== body) {
1322					task.body = body;
1323					mark("body");
1324				}
1325			}
1326			for (const line of patch.addBodyLines ?? []) {
1327				if (line !== "" && !bodyHasLine(task.body, line)) {
