1329					mark("body");
1330				}
1331			}
1332			if (patch.repo !== undefined) {
1333				const repo = normalizeTagValue(patch.repo, "repo");
1334				if (task.repo !== repo) {
1335					if (repo === undefined) delete task.repo;
1336					else task.repo = repo;
1337					mark("repo");
1338				}
1339			}
1340			if (patch.kind !== undefined) {
1341				const kind = normalizeTagValue(patch.kind, "kind");
