1346					);
1347				}
1348				if (task.kind !== kind) {
1349					if (kind === undefined) delete task.kind;
1350					else task.kind = kind;
1351					mark("kind");
1352				}
1353			}
1354			if (patch.hold !== undefined) {
1355				const hold = normalizeHold(patch.hold ?? undefined);
1356				if (!sameHold(task.hold, hold)) {
1357					if (hold) task.hold = hold;
1358					else delete task.hold;
1359					mark("hold");
1360				}
1361			}
1362			if (patch.priority !== undefined) {
1363				const priority = normalizePriority(patch.priority);
1364				if (task.priority !== priority) {
1365					task.priority = priority;
1366					mark("priority");
1367				}
1368			}
1369			if (patch.meta) {
