1028		/** Resolve dependency slugs to work item ids, failing on a missing target. */
1029		private async resolveDeps(deps: Dep[]): Promise<Map<string, number>> {
1030			const resolved = new Map<string, number>();
1031			for (const d of deps) {
1032				if (resolved.has(d.id)) continue;
1033				const item = await this.loadItem(d.id);
1034				if (!item) {
1035					const label = d.type === "blocked-by" ? "blocker" : "dependency";
1036					validation(`${label} "${d.id}" not found`, [
1037						"Create the dependency task first, or choose an existing task id",
1038					]);
1039				}
1040				resolved.set(d.id, item.id);
1041			}
1042			return resolved;
1043		}
