1045		private async requireResolvedDeps(
1046			resolved: Map<string, number>,
1047		): Promise<Map<number, string>> {
1048			const slugs = new Map<number, string>();
1049			for (const [id, workItemId] of resolved) {
1050				const item = await this.loadItem(id);
1051				if (!item || item.id !== workItemId) {
1052					throw new AxiError(
1053						`Dependency "${id}" changed identity or scope while its relation was being written`,
1054						"CONFLICT",
1055					);
1056				}
1057				slugs.set(workItemId, id);
1058			}
1059			return slugs;
1060		}
