103	async function requireExistingBlockers(
104	  store: Store,
105	  deps: Dep[],
106	): Promise<void> {
107	  for (const dep of deps) {
108	    if (dep.type !== "blocked-by") continue;
109	    if (await store.get(dep.id)) continue;
110	    throw new AxiError(`blocker "${dep.id}" not found`, "VALIDATION_ERROR", [
111	      "Create the blocker task first, or choose an existing task id",
112	    ]);
113	  }
114	}
