179	function parsePriority(raw: string | undefined): number | undefined {
180	  if (raw === undefined) return undefined;
181	  if (!/^[0-4]$/.test(raw)) {
182	    throw new AxiError("--priority must be an integer 0-4", "VALIDATION_ERROR");
183	  }
184	  return Number(raw);
