187	function requireTitle(
188	  raw: string,
189	  message: string,
190	  suggestion: string,
191	): string {
192	  if (/[\r\n]/.test(raw)) {
193	    throw new AxiError("Task title must be a single line", "VALIDATION_ERROR");
194	  }
195	  const title = raw.trim();
196	  if (title === "") {
197	    throw new AxiError(message, "VALIDATION_ERROR", [suggestion]);
198	  }
199	  if (extractTags(title).title !== title) {
200	    throw new AxiError(
201	      "Task title must not end with canonical task tags",
202	      "VALIDATION_ERROR",
203	    );
204	  }
205	  return title;
206	}
