208	async function mintAvailableId(
209	  store: Store,
210	  title: string,
211	  prefix?: string,
212	): Promise<string> {
213	  const first = mintId(title, prefix);
214	  if (!(await store.get(first))) return first;
215	
216	  for (const suffix of MINT_SUFFIXES) {
217	    const candidate = mintIdForSuffix(title, suffix, prefix);
218	    if (candidate === first) continue;
219	    if (!(await store.get(candidate))) return candidate;
220	  }
221	
222	  throw new AxiError("Could not mint a unique id for this title", "CONFLICT", [
223	    'Pass an explicit id, e.g. `tasks-axi add <id> "title"`',
224	  ]);
225	}
