227	export async function addCommand(
228	  rawArgs: string[],
229	  context?: TasksContext,
230	): Promise<string> {
231	  const { store } = requireCtx(context);
232	  const args = [...rawArgs];
233	
234	  const kind = requireSafeTagFlagValue("--kind", takeFlag(args, "--kind"));
235	  const repo = requireSafeTagFlagValue("--repo", takeFlag(args, "--repo"));
236	  const body = requireNonEmptyFlagValue("--body", takeBody(args));
237	  const pr = takeFlag(args, "--pr");
238	  const report = takeFlag(args, "--report");
239	  const priority = parsePriority(takeFlag(args, "--priority"));
240	  const deps = parseDeps(args);
241	  const json = takeBoolFlag(args, "--json");
242	  const start = takeBoolFlag(args, "--start");
243	  const queue = takeBoolFlag(args, "--queue");
244	  const mint = takeBoolFlag(args, "--mint");
245	  const rawPrefix = takeFlag(args, "--prefix");
246	  const titleFlag = takeFlag(args, "--title");
247	
248	  if (start && queue) {
249	    throw new AxiError(
250	      "Use only one of --start or --queue",
251	      "VALIDATION_ERROR",
252	    );
253	  }
254	  if (rawPrefix !== undefined && !mint) {
255	    throw new AxiError(
256	      "--prefix can only be used with --mint",
257	      "VALIDATION_ERROR",
258	      ['Run `tasks-axi add "<title>" --mint --prefix <p>`, or omit --prefix'],
259	    );
260	  }
261	  const prefix = requireNonEmptySingleLineFlagValue("--prefix", rawPrefix);
262	
263	  const positionals = requirePositionals(
264	    args,
265	    mint ? 0 : 1,
266	    titleFlag === undefined ? (mint ? 1 : 2) : mint ? 0 : 1,
267	    ADD_HELP.split("\n")[0],
268	  );
269	  let id: string;
270	  let title: string;
271	  if (mint) {
272	    title = requireTitle(
273	      titleFlag ?? positionals[0] ?? "",
274	      "--mint requires a title",
275	      'Run `tasks-axi add "<title>" --mint`',
276	    );
277	    id = await mintAvailableId(store, title, prefix);
278	  } else {
279	    id = validateId(requireId(positionals[0], "id"));
280	    title = requireTitle(
281	      titleFlag ?? positionals[1] ?? "",
282	      "A title is required",
283	      'Run `tasks-axi add <id> "<title>"`',
284	    );
285	  }
286	
287	  if (deps.some((dep) => dep.id === id)) {
288	    throw new AxiError("A task cannot block itself", "VALIDATION_ERROR");
289	  }
290	  await requireExistingBlockers(store, deps);
291	  const links = parseLinks(pr, report);
292	
293	  if (!mint) {
294	    const existing = await store.get(id);
295	    if (existing) {
296	      const all = (await store.list({})).items;
297	      return renderMutation({
298	        json,
299	        confirm: `add ${id} already exists -> ${stateLabel(existing.state)}`,
300	        already: true,
301	        jsonPayload: {
302	          ok: true,
303	          action: "add",
304	          already: true,
305	          task: taskToJson(existing, all),
306	        },
307	        detail: renderTaskDetail(
308	          existing,
309	          all,
310	          false,
311	          showFullTextHint(existing),
312	        ),
313	        suggestions:
314	          existing.kind === "public-followup"
315	            ? []
316	            : getSuggestions({
317	                action: "add",
318	                id,
319	                state: existing.state,
320	                globals: context?.suggestionGlobals,
321	              }),
322	      });
323	    }
324	  }
325	
326	  const state: State = start ? "in_flight" : "queued";
327	  const input: TaskInput = {
328	    id,
329	    title,
330	    state,
331	    deps,
332	    links,
333	  };
334	  if (kind) input.kind = kind;
335	  if (repo) input.repo = repo;
336	  if (body !== undefined) input.body = body;
337	  if (priority !== undefined) input.priority = priority;
338	
339	  const task = await store.create(input);
340	  const all = (await store.list({})).items;
341	  return renderMutation({
342	    json,
343	    confirm: `added ${id}${addAttrs(task)} -> ${stateLabel(task.state)}`,
344	    jsonPayload: { ok: true, action: "add", task: taskToJson(task, all) },
345	    detail: renderTaskDetail(task, all, false, showFullTextHint(task)),
346	    suggestions: getSuggestions({
347	      action: "add",
348	      id,
349	      state: task.state,
350	      globals: context?.suggestionGlobals,
351	    }),
352	  });
353	}
