355	/** The `(kind, repo X)` parenthetical for an add confirmation, omitted when bare. */
356	function addAttrs(task: { kind?: string; repo?: string }): string {
357	  const parts: string[] = [];
358	  if (task.kind) parts.push(task.kind);
359	  if (task.repo) parts.push(`repo ${task.repo}`);
360	  return parts.length > 0 ? ` (${parts.join(", ")})` : "";
