363	export async function listCommand(
364	  rawArgs: string[],
365	  context?: TasksContext,
366	): Promise<string> {
367	  const { store } = requireCtx(context);
368	  const args = [...rawArgs];
369	
370	  const { extraDefs } = parseFields(
371	    takeFlag(args, "--fields"),
372	    LIST_EXTRA_FIELDS,
373	  );
374	  const state = parseListStateFlag(takeFlag(args, "--state"));
375	  const repo = requireNonEmptySingleLineFlagValue(
376	    "--repo",
377	    takeFlag(args, "--repo"),
378	  );
379	  const kind = requireNonEmptySingleLineFlagValue(
380	    "--kind",
381	    takeFlag(args, "--kind"),
382	  );
383	  const onlyBlocked = takeBoolFlag(args, "--blocked");
384	  const limit = parseOptionalNonNegativeIntegerFlag(
385	    "--limit",
386	    takeFlag(args, "--limit"),
387	  );
388	  requirePositionals(args, 0, 0, LIST_HELP.split("\n")[0]);
389	
390	  // The full set is needed to derive `blocked` (a dep-graph projection), so the
391	  // list command filters in the CLI rather than pushing every filter to the
392	  // store. The store's own filtering is exercised by `home` and `ready`.
393	  const all = (await store.list({})).items;
394	  const blocked = blockedIds(all);
395	  const held = new Set(heldTasks(all).map((t) => t.id));
396	
397	  let matched = all;
398	  if (state === "held") {
399	    matched = matched.filter((t) => held.has(t.id));
400	  } else if (state) {
401	    matched = matched.filter((t) => t.state === state);
402	  }
403	  if (repo) matched = matched.filter((t) => t.repo === repo);
404	  if (kind) matched = matched.filter((t) => (t.kind ?? "task") === kind);
405	  if (onlyBlocked) matched = matched.filter((t) => blocked.has(t.id));
406	
407	  const total = matched.length;
408	  const items =
409	    limit !== undefined && limit >= 0 ? matched.slice(0, limit) : matched;
410	  const isEmpty = total === 0;
411	
412	  const countLine = formatCountLine({
413	    count: items.length,
414	    limit,
415	    totalCount: total,
416	  });
417	
418	  const blocks: string[] = [countLine];
419	  if (isEmpty) {
420	    blocks.push(emptyState(state, repo, kind, onlyBlocked));
421	  } else {
422	    blocks.push(renderTaskList("tasks", items, all, extraDefs));
423	  }
424	  blocks.push(
425	    renderHelp(
426	      getSuggestions({
427	        action: "list",
428	        isEmpty,
429	        globals: context?.suggestionGlobals,
430	        filters: {
431	          ...(state !== undefined ? { state } : {}),
432	          ...(repo !== undefined ? { repo } : {}),
433	          ...(kind !== undefined ? { kind } : {}),
434	        },
435	      }),
436	    ),
437	  );
438	  return renderOutput(blocks);
439	}
440	
441	function emptyState(
442	  state: string | undefined,
443	  repo: string | undefined,
444	  kind: string | undefined,
445	  blocked: boolean,
446	): string {
