679	export async function mvCommand(
680	  rawArgs: string[],
681	  context?: TasksContext,
682	): Promise<string> {
683	  const { store, config } = requireCtx(context);
684	  const args = [...rawArgs];
685	
686	  const json = takeBoolFlag(args, "--json");
687	  const to = requireNonEmptySingleLineFlagValue("--to", takeFlag(args, "--to"));
688	  if (to === undefined) {
689	    throw new AxiError("--to <path-or-dir> is required", "VALIDATION_ERROR", [
690	      "Name the destination backlog, e.g. `--to ../other/data/backlog.md`",
691	    ]);
692	  }
693	  requireNoUnknownFlags(args);
694	  const positionals = args.filter((arg) => !arg.startsWith("-"));
695	  if (positionals.length === 0) {
696	    throw new AxiError("Expected at least one task id", "VALIDATION_ERROR", [
697	      MV_HELP.split("\n")[0],
698	    ]);
699	  }
700	  const ids = [...new Set(positionals.map((p) => requireId(p, "id")))];
701	
702	  const capabilities = store.capabilities();
703	  if (!capabilities.fileMoves) {
704	    throw new AxiError(
705	      `The ${capabilities.backend} backend does not support file-backed moves`,
706	      "UNSUPPORTED",
707	      ["ADO area-path moves will be wired to `mv` in a follow-up"],
708	    );
709	  }
710	
711	  const targetPath = resolveBacklogTarget(to);
712	  if (resolve(targetPath) === resolve(config.path)) {
713	    throw new AxiError(
714	      "--to resolves to the current backlog",
715	      "VALIDATION_ERROR",
716	    );
717	  }
718	
719	  const tasks: Task[] = [];
720	  for (const id of ids) {
721	    const task = await store.get(id);
722	    if (!task) throw notFound(id, { globals: context?.suggestionGlobals });
723	    tasks.push(task);
724	  }
725	
726	  const target = new MarkdownStore({ path: targetPath });
727	  for (const id of ids) {
728	    if (await target.get(id)) {
729	      throw new AxiError(
730	        `Task "${id}" already exists in the destination backlog`,
731	        "CONFLICT",
732	      );
733	    }
734	  }
735	
736	  if (store instanceof MarkdownStore) {
737	    await store.moveManyTo(ids, target);
738	  } else if (ids.length === 1) {
739	    await target.create(taskToInput(tasks[0]));
740	    await store.remove(ids[0]);
741	  } else {
742	    throw new AxiError(
743	      "Moving multiple tasks at once requires the markdown backend",
744	      "UNSUPPORTED",
745	    );
746	  }
747	
748	  const single = ids.length === 1;
749	  return renderMutation({
750	    json,
751	    confirm: single
752	      ? `mv ${ids[0]} -> ${targetPath}`
753	      : `mv ${ids.join(" ")} -> ${targetPath}`,
754	    jsonPayload: {
755	      ok: true,
756	      action: "mv",
757	      ...(single ? { id: ids[0] } : { ids }),
758	      from: config.path,
759	      to: targetPath,
760	    },
761	    suggestions: getSuggestions({
762	      action: "mv",
763	      id: ids[0],
764	      globals: context?.suggestionGlobals,
765	    }),
766	  });
767	}
