116	function requireSafeTagFlagValue(
117	  flag: string,
118	  value: string | undefined,
119	): string | undefined {
120	  const checked = requireNonEmptySingleLineFlagValue(flag, value);
121	  if (checked === undefined) return undefined;
122	  if (/[()]/.test(checked)) {
123	    throw new AxiError(
124	      `${flag} must not contain parentheses`,
125	      "VALIDATION_ERROR",
126	      [`Pass ${flag}=... without parentheses`],
127	    );
128	  }
129	  return checked.trim();
130	}
