132	function requireTypedLinkUrl(
133	  flag: "--pr" | "--report",
134	  kind: TaskLink["kind"],
135	  value: string | undefined,
136	): string | undefined {
137	  const checked = requireNonEmptyFlagValue(flag, value);
138	  if (checked === undefined) return undefined;
139	  if (/[\r\n]/.test(checked)) {
140	    throw new AxiError(`${flag} must be a single line`, "VALIDATION_ERROR", [
141	      `Pass ${flag}=... without line breaks`,
142	    ]);
143	  }
144	  // pr URLs must already be canonical; padded input is rejected, not trimmed
145	  const url = kind === "pr" ? checked : checked.trim();
146	  if (
147	    !deriveLinks(url).some((link) => link.kind === kind && link.url === url)
148	  ) {
149	    const expected =
150	      kind === "pr" ? PR_URL_EXPECTED : "a data/<id>/report.md path";
151	    throw new AxiError(`${flag} must be ${expected}`, "VALIDATION_ERROR");
152	  }
153	  return url;
154	}
