156	function parseLinks(pr?: string, report?: string): TaskLink[] {
157	  const links: TaskLink[] = [];
158	  const checkedPr = requireTypedLinkUrl("--pr", "pr", pr);
159	  const checkedReport = requireTypedLinkUrl("--report", "report", report);
160	  if (checkedPr !== undefined) links.push({ kind: "pr", url: checkedPr });
161	  if (checkedReport !== undefined) {
162	    links.push({ kind: "report", url: checkedReport });
163	  }
164	  return links;
165	}
