169	function parseListStateFlag(raw: string | undefined): ListState | undefined {
170	  if (raw === undefined) return undefined;
171	  if (raw === "held") return raw;
172	  if ((STATES as readonly string[]).includes(raw)) return raw as State;
173	  throw new AxiError(
174	    "--state must be one of queued, in_flight, done, held",
175	    "VALIDATION_ERROR",
176	  );
177	}
