234	  const kind = requireSafeTagFlagValue("--kind", takeFlag(args, "--kind"));
235	  const repo = requireSafeTagFlagValue("--repo", takeFlag(args, "--repo"));
236	  const body = requireNonEmptyFlagValue("--body", takeBody(args));
237	  const pr = takeFlag(args, "--pr");
238	  const report = takeFlag(args, "--report");
239	  const priority = parsePriority(takeFlag(args, "--priority"));
240	  const deps = parseDeps(args);
241	  const json = takeBoolFlag(args, "--json");
242	  const start = takeBoolFlag(args, "--start");
243	  const queue = takeBoolFlag(args, "--queue");
244	  const mint = takeBoolFlag(args, "--mint");
245	  const rawPrefix = takeFlag(args, "--prefix");
246	  const titleFlag = takeFlag(args, "--title");
