261	  const prefix = requireNonEmptySingleLineFlagValue("--prefix", rawPrefix);
262	
263	  const positionals = requirePositionals(
264	    args,
265	    mint ? 0 : 1,
266	    titleFlag === undefined ? (mint ? 1 : 2) : mint ? 0 : 1,
267	    ADD_HELP.split("\n")[0],
268	  );
269	  let id: string;
270	  let title: string;
271	  if (mint) {
