274	      "--mint requires a title",
275	      'Run `tasks-axi add "<title>" --mint`',
276	    );
277	    id = await mintAvailableId(store, title, prefix);
278	  } else {
279	    id = validateId(requireId(positionals[0], "id"));
280	    title = requireTitle(
