299	        confirm: `add ${id} already exists -> ${stateLabel(existing.state)}`,
300	        already: true,
301	        jsonPayload: {
302	          ok: true,
303	          action: "add",
304	          already: true,
305	          task: taskToJson(existing, all),
306	        },
307	        detail: renderTaskDetail(
308	          existing,
309	          all,
310	          false,
311	          showFullTextHint(existing),
312	        ),
313	        suggestions:
314	          existing.kind === "public-followup"
