326	  const state: State = start ? "in_flight" : "queued";
327	  const input: TaskInput = {
328	    id,
329	    title,
330	    state,
331	    deps,
332	    links,
333	  };
334	  if (kind) input.kind = kind;
335	  if (repo) input.repo = repo;
336	  if (body !== undefined) input.body = body;
337	  if (priority !== undefined) input.priority = priority;
338	
339	  const task = await store.create(input);
